void inspect(View&v){auto list=v.learnerActions();int eligible=0;for(const auto&a:list.array())if(a.object().at("action").string()!="navigate"){++eligible;}auto&menu=control<juce::ComboBox>(v,"shared-procedure-actions");auto&submit=control<Button>(v,"shared-procedure-submit");ck(eligible>0,"fixture must have eligible action");if(eligible==1){++direct;ck(!menu.isVisible()&&!v.selectedSchema().null()&&submit.isEnabled(),"sole operation must configure an enabled direct form without dropdown");ck(submit.getTitle().startsWith("Submit current manual action: "),"direct action names actual operation");}else{++alternatives;ck(menu.isVisible()&&v.selectedSchema().null()&&!submit.isEnabled(),"real alternatives remain explicit with no default operation");}ck(v.retainedHistoryCount()==0,"presentation does not submit or advance owner");}
