void fill(View& view,const V& schema,const V& value,const std::string& path="input"){
 if(const auto* constant=schema.find("const")){ck(*constant==value,"Fixture changed source/prior-choice constant");if(const auto* marked=schema.find("source_constant");marked&&*marked==V(true)&&schema.find("input_role")&&*schema.find("input_role")==V("source_binding")){ck(control<juce::Label>(view,"typed-label-"+path).getText().startsWith("Printed / protocol binding: "),"Source binding not visibly labeled");ck(!find(view,"typed-field-"+path),"Printed source binding became editable");}return;}
 if(const auto* choices=schema.find("enum")){auto it=std::find(choices->array().begin(),choices->array().end(),value);ck(it!=choices->array().end(),"Fixture enum mismatch "+path);auto& c=control<juce::ComboBox>(view,"typed-field-"+path);c.setSelectedId(static_cast<int>(it-choices->array().begin()+1),juce::dontSendNotification);if(c.onChange)c.onChange();return;}
 const auto& kinds=f(schema,"type");const auto kind=kinds.isString()?kinds.string():kinds.array().front().string();
 if(value.null()&&kind!="boolean"){control<juce::ToggleButton>(view,"typed-unknown-"+path).setToggleState(true,juce::dontSendNotification);return;}
 if(kind=="object"){for(const auto& p:f(schema,"properties").object()){const auto* val=value.find(p.first);if(!val)continue;if(auto* c=dynamic_cast<juce::ToggleButton*>(find(view,"typed-include-"+path+"/"+p.first)))c->setToggleState(true,juce::dontSendNotification);fill(view,p.second,*val,path+"/"+p.first);}return;}
 if(kind=="array"){if(num(f(schema,"minItems"))!=num(f(schema,"maxItems"))){auto& c=control<juce::ComboBox>(view,"typed-count-"+path);c.setSelectedId(static_cast<int>(value.array().size()+1),juce::dontSendNotification);c.onChange();invalidateLookup(view);}for(std::size_t i=0;i<value.array().size();++i)fill(view,f(schema,"items"),value.array()[i],path+"/"+std::to_string(i));return;}
 if(kind=="boolean"){if(auto* c=dynamic_cast<juce::ComboBox*>(find(view,"typed-field-"+path))){c->setSelectedId(value.null()?3:value.boolean()?1:2,juce::dontSendNotification);if(c->onChange)c->onChange();}else control<juce::ToggleButton>(view,"typed-field-"+path).setToggleState(value.boolean(),juce::dontSendNotification);return;}
 if(auto* unknown=dynamic_cast<juce::ToggleButton*>(find(view,"typed-unknown-"+path)))unknown->setToggleState(false,juce::dontSendNotification);
 control<juce::TextEditor>(view,"typed-field-"+path).setText(ju(kind=="integer"?std::to_string(num(value)):kind=="number"?std::get<json::Number>(value.data).token:value.string()),false);
}

void groupChecks(){using namespace desktop::manual_workspace;using O=V::Object;const V binding=O{{"source_key","exact-source"},{"contract_sha256","contract"},{"own_closure_sha256","closure"}};const V active=O{{"state","active"},{"needs_manual_release",false},{"self_check_visible",false}};auto event=[&](int revision){return V(O{{"action","submit"},{"reported",O{{"own_report","explicit learner input"},{"count",V::fromInteger(revision)}}},{"before",active},{"after",active},{"pass",V::fromInteger(1)},{"revision",V::fromInteger(revision)},{"frame",V::fromInteger(3)},{"node","original-node-"+std::to_string(revision)},{"source_key","exact-source"},{"contract_sha256","contract"},{"own_closure_sha256","closure"},{"observed_performance",false},{"grants_credit",false}});};auto a=event(1),b=event(2);std::vector<V> h{a,b};const auto original=h;auto groups=reportGroups(h,binding,false);ck(groups.array().size()==1&&groups.array()[0].object().at("reports").array().size()==2,"adjacent committed reports group without merging facts");ck(h==original,"group projection cannot mutate original history");const auto& reports=groups.array()[0].object().at("reports").array();ck(reports[0].object().at("event")==a&&reports[1].object().at("event")==b,"every report retains exact original payload node source and retry identity");ck(reports[0].object().at("original_event_number")==V::fromInteger(1)&&reports[1].object().at("original_event_number")==V::fromInteger(2),"group preserves separate event positions");ck(reportGroups(h,binding,true).array().empty(),"restricted Source role cannot project report groups");ck(reportGroups(h,V(),false).array().empty(),"missing exact source binding cannot group");
 for(const auto& action:{"release","reveal","reveal_recorded_order","retry","cancel","stop","navigate","choose","begin"}){auto barrier=event(3);barrier.object()["action"]=action;auto c=event(4),d=event(5);auto g=reportGroups({a,b,barrier,c,d},binding,false);ck(g.array().size()==2&&g.array()[0].object().at("reports").array().size()==2&&g.array()[1].object().at("reports").array().size()==2,"control release reveal retry and choice boundaries never merge reports");}
 for(const auto& field:{"needs_manual_release","manual_release_debt","external_source_stop_debt","self_check_visible"}){auto boundary=event(3);boundary.object()["after"].object()[field]=true;auto g=reportGroups({a,b,boundary,event(4),event(5)},binding,false);ck(g.array().size()==2,"physical release stop or exposure boundary splits visual group");}
 for(const auto& field:{"source_key","contract_sha256","own_closure_sha256"}){auto other=event(3);other.object()[field]="different";auto g=reportGroups({a,b,other,event(4),event(5)},binding,false);ck(g.array().size()==2,"different exact source binding cannot join group");}
 for(const auto& field:{"pass","frame","revision"}){auto other=event(3);other.object()[field]=V::fromInteger(9);auto g=reportGroups({a,b,other},binding,false);ck(g.array().size()==2,"pass frame and nonadjacent revision retain separate retry groups");}
 for(const auto& field:{"observed_performance","grants_credit"}){auto invalid=event(3);invalid.object()[field]=true;auto g=reportGroups({invalid},binding,false);ck(g.array().empty(),"grouping cannot project observed performance or credit claims");}auto source=event(3);source.object()["role"]="trusted_source_player";ck(reportGroups({source},binding,false).array().empty(),"provider-only input cannot enter learner report cards");auto revealed=event(3);revealed.object()["after"].object()["printed_self_check"]="private answer";ck(reportGroups({revealed},binding,false).array().empty(),"printed answer exposure is not a report grouping input");auto missing=event(3);missing.object().erase("reported");ck(reportGroups({missing},binding,false).array().empty(),"missing report cannot fabricate a grouped fact");ck(reportGroups({V("malformed")},binding,false).array().empty(),"malformed event fails closed");
}

void pageChecks(){desktop::TypedManualForm form;form.setSize(920,680);using O=V::Object;form.configure(O{{"type","object"},{"properties",O{}},{"required",V::Array{}},{"additionalProperties",false}},{},[]{return true;});const auto full=std::string(8191,'a')+"♩"+std::string(8190,'b')+"🎵"+std::string(2500,'c');form.setCommittedReportSummary({full});const auto layouts=form.historyLayoutCount();form.setCommittedReportSummary({full});ck(form.historyLayoutCount()==layouts,"unchanged grouped report text does not rebuild layout");auto&text=control<juce::TextEditor>(form,"committed-report-page");auto&next=control<juce::TextButton>(form,"committed-reports-next");auto&previous=control<juce::TextButton>(form,"committed-reports-previous");ck(text.isReadOnly()&&!previous.isEnabled(),"full grouped reports are read-only and first page has no previous");std::string joined;int pages=0;for(;;){const auto page=text.getText().toStdString();ck(page.size()<=8192,"report text layout remains bounded per page");joined+=page;++pages;if(!next.isEnabled())break;if(pages>8)throw std::runtime_error("report page fixture watchdog");next.onClick();}ck(joined==full+"\n"&&pages==3,"numbered report pages preserve exact complete UTF8 with no lost or duplicate bytes");ck(previous.isEnabled(),"last page exposes explicit previous navigation");ck(control<juce::Label>(form,"committed-reports-page-number").getText()=="Committed reports - page 3 of 3","page heading has exact readable encoding");form.setHistorySummary({"Ordinary compact history"});ck(!control<juce::Component>(form,"committed-reports-panel").isVisible()&&text.getText().isEmpty(),"leaving grouped mode clears old full report pages");}

